using Microsoft.Dynamics.AX.Security.Management.Domain;
using Microsoft.Dynamics.AX.Security.Management.Domain.Duty;

public class NDXDutyTable extends common
{
}

Method.Source:
    /// <summary>
    /// PaffH 18.01.21
    /// find NDXDutyTable
    /// </summary>
/// <param name = "_DutyIdentifier">NDXDutyIdentifier</param>
/// <param name = "_forUpdate">boolean</param>
/// <returns>NDXDutyTable</returns>
   static public NDXDutyTable find(NDXDutyIdentifier _DutyIdentifier,
    boolean _forUpdate = false)
{
    NDXDutyTable   nDXDutyTable;

    nDXDutyTable.selectForUpdate(_forUpdate);

    select firstonly nDXDutyTable
        where nDXDutyTable.DutyIdentifier == _DutyIdentifier;
    return nDXDutyTable;
}

/// <summary>
/// PaffH 18.01.21
/// find or create NDXDutyTable
/// </summary>
/// <param name = "_DutyIdentifier">NDXDutyIdentifier</param>
/// <param name = "_insertNewRecord">boolean</param>
/// <returns>NDXDutyTable</returns>
static public NDXDutyTable findOrCreate(NDXDutyIdentifier _DutyIdentifier,
    boolean _insertNewRecord = true)
{
    NDXDutyTable   nDXDutyTable;
    nDXDutyTable = NDXDutyTable::find(_DutyIdentifier, true);
    if (!nDXDutyTable)
    {
        nDXDutyTable.DutyIdentifier = _DutyIdentifier;
        if (_insertNewRecord)
        {
            nDXDutyTable.insert();
        }
    }
    return nDXDutyTable;
}

/// <summary>
/// PaffH 18.01.21
/// fill NDXDutyTable from duty-object
/// </summary>
/// <param name = "_Duty">Duty</param>
/// <param name = "updatedUtcDateTime">NDXUpdatedUTCDateTime</param>
/// <param name = "isReferencedInRole">is duty referenced in role? (NoYes::No)</param>
/// <returns>NDXDutyTable</returns>
static public NDXDutyTable saveFromDuty(Duty _Duty, NDXUpdatedUTCDateTime updatedUtcDateTime, NDXIsReferencedInRole isReferencedInRole = NoYes::No)
{
    NDXDutyTable nDXDutyTable;
    nDXDutyTable = NDXDutyTable::findOrCreate(_Duty.Identifier, false);
    nDXDutyTable.UpdatedUTCDateTime = updatedUtcDateTime;
    nDXDutyTable.IsReferencedInRole = isReferencedInRole;
    nDXDutyTable.DutyName = _Duty.Name;
    nDXDutyTable.Description = _Duty.Description;
    if (nDXDutyTable.validateWrite())
    {
        ttsbegin;
        nDXDutyTable.write();
        ttscommit;
    }
    return nDXDutyTable;
}

/// <summary>
/// PaffH 20.01.21
/// delete records not updated
/// </summary>
/// <param name = "_updatedUtcDateTime">NDXUpdatedUTCDateTime</param>
/// <param name = "_logger">NDXLoggerSecurityInformationClass</param>
/// <returns>counter deleted records</returns>
static public int deleteNotUpdated(NDXUpdatedUTCDateTime _updatedUtcDateTime, NDXLoggerSecurityInformationClass _logger)
{
    NDXDutyTable nDXDutyTable;
    NDXArgsLoggerSecuritiyInformation argsLogger = new NDXArgsLoggerSecuritiyInformation();
    argsLogger.parmLogActivity(strFmt("@NDX:NDXDeleteRecordsInTable", tableId2PName(nDXDutyTable.TableId)));
    _logger.LogLineCreate(argsLogger);

    NDXHelperTable::skipForDelete(nDXDutyTable);
    delete_from nDXDutyTable
        where nDXDutyTable.UpdatedUTCDateTime != _updatedUtcDateTime;

    argsLogger.parmCounter(int642int(nDXDutyTable.RowCount()));
    _logger.LogLineChange(argsLogger);

    return int642int(nDXDutyTable.RowCount());
}
